interface Document {
  id: string;
  fileName: string;
  originalName: string;
  documentType: string;
  status: 'uploaded' | 'queued' | 'processing' | 'processed' | 'failed' | 'duplicate';
  createdAt: string;
  notes?: string;
  tags?: string[];
  extractedData?: {
    amount: number;
    vendor: {
      name: string;
      address?: string;
      phone?: string;
      email?: string;
    };
    date: string;
    description: string;
    category: string;
    subcategory?: string;
    items?: Array<{
      name: string;
      quantity: number;
      unit: string;
      price: number;
      total: number;
    }>;
    tax?: {
      cgst: number;
      sgst: number;
      igst: number;
      total: number;
    };
    paymentMethod?: string;
    referenceNumber?: string;
    invoice_number?: string;
    gstin?: string;
    seller_gstin?: string;
  };
  extractedDataVerification?: {
    status?: 'pending' | 'verified';
    verifiedAt?: string;
    acceptedForEmissions?: boolean;
    correctionCount?: number;
  };
  duplicateDetection?: {
    isDuplicate: boolean;
    duplicateType: string | null;
    decisionTier?: string | null;
    matchedDocumentId: string;
    duplicateReasons: string[];
  };
  processingResults?: {
    confidence: number;
    processingTime: number;
    errors: string[];
    warnings: string[];
    ocrValidation?: OcrValidation | null;
    billQualityRemediation?: {
      band: 'review_required';
      qualityScore: number;
      qualityPct: number;
      summary: string;
      suggestions: Array<{
        id: string;
        severity: 'important' | 'recommended' | 'info';
        message: string;
        action: 'verify' | 'reupload' | 'metered_upload';
      }>;
      capabilities: {
        processed: boolean;
        spendCarbon: boolean;
        activityUplift: boolean;
        requiresVerification: boolean;
      };
      carbonAnalysisThreshold: number;
      activityUpliftThreshold: number;
      minProcessingThreshold: number;
    } | null;
  };
  ocrValidation?: OcrValidation | null;
  carbonFootprint?: {
    co2Emissions: number;
    emissionFactor: number;
    calculationMethod: string;
    sustainabilityScore: number;
    /** Spend-based (₹ only) estimate, kept out of the inventory total until quantities are confirmed. */
    screeningCo2Emissions?: number;
    emissionBreakdown?: {
      scope1?: number;
      scope2?: number;
      scope3?: number;
    };
  };
  metadata?: {
    transactionMapping?: 'company' | 'product';
    ocr?: {
      gateRejectionReason?: string;
      rejectionReason?: string;
      strategy?: string;
      engines?: string[];
    };
  };
}

interface TabPanelProps {
  children?: React.ReactNode;
  index: number | number[];
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;
  const indexes = Array.isArray(index) ? index : [index];
  const active = indexes.includes(value);

  return (
    <div
      role="tabpanel"
      hidden={!active}
      id={`simple-tabpanel-${indexes[0]}`}
      aria-labelledby={`simple-tab-${indexes[0]}`}
      {...other}
    >
      {active && (
        <Box sx={{ pt: 2, px: 0, pb: 0 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

