import React, { useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Typography,
} from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';
import ClarificationQueue from '../clarification/ClarificationQueue';
import { clarificationGroupKey } from '../clarification/clarificationModel';
import {
  formatImportAmount,
  formatImportDate,
  type DuplicateAccountingRow,
  type ImportClarificationRequest,
  type InvalidAccountingRow,
  type LastAccountingImportResult,
  type PendingBillUpload,
  type PersistFailureAccountingRow,
} from './accountingImportResult';

export interface ClarificationDraft {
  text: string;
  quantity: string;
  unit: string;
  originAirport: string;
  destinationAirport: string;
  answers: Record<string, string>;
  saved: boolean;
  summary?: string;
}

export interface ClarificationSaveEntry {
  transactionId: string;
  draft: ClarificationDraft;
  body: Record<string, unknown>;
}

type ReviewTone = 'ready' | 'unclear' | 'saved' | 'duplicate' | 'invalid' | 'failed';

interface ReviewRow {
  key: string;
  tone: ReviewTone;
  status: string;
  rowIndex?: number;
  sourceId?: string | null;
  description: string;
  amount?: number;
  date?: string | Date;
  category?: string;
  detail?: string;
  clarification?: ImportClarificationRequest;
}

const PAGE_SIZE = 25;

const toneLabel: Record<ReviewTone, string> = {
  ready: 'Ready',
  unclear: 'Needs clarification',
  saved: 'Clarification saved',
  duplicate: 'Duplicate',
  invalid: 'Invalid',
  failed: 'Failed',
};

interface ImportFileReviewProps {
  result: LastAccountingImportResult;
  drafts: Record<string, ClarificationDraft>;
  deciding: boolean;
  onSaveGroup: (entries: ClarificationSaveEntry[]) => void;
  onConfirm: () => void;
  onCancel: () => void;
}

const ImportFileReview: React.FC<ImportFileReviewProps> = ({
  result,
  drafts,
  deciding,
  onSaveGroup,
  onConfirm,
  onCancel,
}) => {
  const theme = useTheme();
  const [page, setPage] = useState(0);
  const [queueOpen, setQueueOpen] = useState(false);
  const [openClarificationId, setOpenClarificationId] = useState<string | null>(null);
  const clarifications = useMemo(
    () => result.pendingClarifications || [],
    [result.pendingClarifications],
  );
  const clarificationById = useMemo(() => {
    const map = new Map<string, ImportClarificationRequest>();
    clarifications.forEach((row) => map.set(row.transactionId, row));
    return map;
  }, [clarifications]);
  const billById = useMemo(() => {
    const map = new Map<string, PendingBillUpload>();
    result.pendingBillUpload.forEach((row) => {
      if (row.transactionId) map.set(row.transactionId, row);
    });
    return map;
  }, [result.pendingBillUpload]);

  const rows = useMemo(() => {
    const importedRows: ReviewRow[] = result.imported.map((row, index) => {
      const id = row.id ? String(row.id) : '';
      const clarification = id ? clarificationById.get(id) : undefined;
      const draft = id ? drafts[id] : undefined;
      const bill = id ? billById.get(id) : undefined;
      let tone: ReviewTone = 'ready';
      let status = 'Ready';
      if (clarification && !draft?.saved) {
        tone = 'unclear';
        status = toneLabel.unclear;
      } else if (clarification && draft?.saved) {
        tone = 'ready';
        status = toneLabel.ready;
      } else if (bill) {
        status = 'Bill can be added later';
      }
      return {
        key: id || row.sourceId || `imported-${row.rowIndex ?? index}`,
        tone,
        status,
        rowIndex: row.rowIndex,
        sourceId: row.sourceId,
        description: clarification?.description || row.description || 'No description',
        amount: row.amount,
        date: row.date,
        category: row.category,
        clarification,
      };
    });
    const importedIds = new Set(result.imported.map((row) => (row.id ? String(row.id) : '')).filter(Boolean));
    const missingClarifications: ReviewRow[] = clarifications
      .filter((row) => !importedIds.has(row.transactionId))
      .map((row) => ({
        key: `clarify-${row.transactionId}`,
        tone: (drafts[row.transactionId]?.saved ? 'ready' : 'unclear') as ReviewTone,
        status: drafts[row.transactionId]?.saved ? toneLabel.ready : toneLabel.unclear,
        rowIndex: row.rowIndex ?? undefined,
        sourceId: row.sourceId,
        description: row.description || row.title || 'Unclear transaction',
        amount: row.amount,
        date: row.date || undefined,
        category: row.category,
        clarification: row,
      }));
    const extras: ReviewRow[] = [
      ...result.duplicates.map((row, index) => problemRow('duplicate', row, index, (row.reasons || []).join('; '))),
      ...result.invalidRows.map((row, index) => problemRow('invalid', row, index, (row.errors || []).join('; '))),
      ...result.persistFailures.map((row, index) => problemRow('failed', row, index, row.error || '')),
    ];
    return [...missingClarifications, ...importedRows, ...extras];
  }, [billById, clarificationById, clarifications, drafts, result]);

  const unclearCount = clarifications.filter((row) => !drafts[row.transactionId]?.saved).length;
  const savedCount = clarifications.filter((row) => drafts[row.transactionId]?.saved).length;
  const openItems = useMemo(
    () => clarifications.filter((row) => !drafts[row.transactionId]?.saved),
    [clarifications, drafts]
  );
  const preferredKey = useMemo(() => {
    const match = openItems.find((row) => row.transactionId === openClarificationId);
    return match ? clarificationGroupKey(match) : null;
  }, [openClarificationId, openItems]);
  const pageRows = rows.slice(page * PAGE_SIZE, page * PAGE_SIZE + PAGE_SIZE);
  const toneColor = (tone: ReviewTone) => {
    if (tone === 'unclear') return theme.palette.warning.main;
    if (tone === 'saved') return theme.palette.info.main;
    if (tone === 'duplicate') return theme.palette.text.secondary;
    if (tone === 'ready') return theme.palette.divider;
    return theme.palette.error.main;
  };

  return (
    <Box
      component="section"
      aria-label="Imported transactions"
      sx={{ mb: 3, minWidth: 0 }}
    >
      <Typography variant="h6" sx={{ fontWeight: 700 }}>
        {result.fileName}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5, mb: 1.5 }}>
        {`${result.totals.imported.toLocaleString('en-IN')} imported transaction${result.totals.imported === 1 ? '' : 's'}. Amber rows need a clarification. Add clarifications for a group, and those rows return to the normal colour. When every amber row is done, carbon calculation starts. Cancel deletes this uploaded file.`}
      </Typography>
      <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" sx={{ mb: 1.5 }}>
        <Chip size="small" label={`${result.imported.length} in this file`} sx={{ bgcolor: alpha(theme.palette.success.main, 0.15) }} />
        <Chip size="small" label={`${unclearCount} need clarification`} sx={{ bgcolor: alpha(theme.palette.warning.main, 0.22) }} />
        <Chip size="small" label={`${savedCount} clarification saved`} sx={{ bgcolor: alpha(theme.palette.info.main, 0.16) }} />
        <Chip size="small" label={`${result.duplicates.length} duplicate`} variant="outlined" />
        <Chip size="small" label={`${result.invalidRows.length + result.persistFailures.length} invalid or failed`} sx={{ bgcolor: alpha(theme.palette.error.main, 0.12) }} />
      </Stack>
      {unclearCount > 0 && (
        <Alert severity="warning" sx={{ mb: 1.5 }}>
          Highlighted rows are unclear. Add clarifications once for each group of matching vouchers. Cancel deletes the uploaded file.
        </Alert>
      )}
      {queueOpen && openItems.length > 0 ? (
        <Box sx={{ mb: 1.5 }}>
          <ClarificationQueue
            items={openItems}
            saving={deciding}
            preferredKey={preferredKey}
            onSubmitGroup={(entries) => {
              onSaveGroup(entries.map(({ item, body }) => {
                const saved = body as Record<string, unknown>;
                return {
                  transactionId: item.transactionId,
                  body: saved,
                  draft: {
                    text: String(saved.transactionClarification || ''),
                    quantity: saved.quantity == null ? String(item.quantity || '') : String(saved.quantity),
                    unit: String(saved.unit || item.unit || ''),
                    originAirport: String(saved.originAirport || ''),
                    destinationAirport: String(saved.destinationAirport || ''),
                    answers: Object.fromEntries(
                      Object.entries(saved).flatMap(([key, value]) => {
                        if ([
                          'carbonInputBasis',
                          'quantity',
                          'unit',
                          'transactionClarification',
                          'clarificationWithoutBill',
                          'materialName',
                          'originAirport',
                          'destinationAirport',
                        ].includes(key) || !String(value ?? '').trim()) return [];
                        return [[key, String(value)]];
                      })
                    ),
                    saved: true,
                    summary: String(saved.transactionClarification || ''),
                  },
                };
              }));
            }}
          />
        </Box>
      ) : null}
      {rows.length === 0 ? (
        <Alert severity="info" sx={{ mb: 1.5 }}>
          {result.totals.imported > 0
            ? `${result.totals.imported.toLocaleString('en-IN')} transactions were imported. Row details were not included in this response.`
            : 'No transaction rows were returned for this file.'}
        </Alert>
      ) : (
        <TableContainer sx={{ maxHeight: 640, border: 1, borderColor: 'divider', borderRadius: 1, width: '100%', minWidth: 0, maxWidth: '100%', overflowX: 'auto', WebkitOverflowScrolling: 'touch' }}>
          <Table size="small" stickyHeader>
            <TableHead>
              <TableRow>
                <TableCell>Status</TableCell>
                <TableCell>Row</TableCell>
                <TableCell>Transaction</TableCell>
                <TableCell align="right">Amount</TableCell>
                <TableCell>Date</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {pageRows.map((row) => {
                const draft = row.clarification ? drafts[row.clarification.transactionId] : undefined;
                return (
                  <TableRow
                    key={row.key}
                    sx={{
                      bgcolor: row.tone === 'ready'
                        ? 'transparent'
                        : alpha(toneColor(row.tone), 0.16),
                    }}
                  >
                    <TableCell sx={{ whiteSpace: 'nowrap' }}>
                      <Chip
                        size="small"
                        label={row.status}
                        sx={{ bgcolor: alpha(toneColor(row.tone), 0.2), fontWeight: 600 }}
                      />
                    </TableCell>
                    <TableCell>{row.rowIndex ?? '—'}</TableCell>
                    <TableCell>
                      <Typography variant="body2" sx={{ fontWeight: 600 }}>{row.description}</Typography>
                      <Typography variant="caption" color="text.secondary" display="block">
                        {[row.category, row.sourceId].filter(Boolean).join(' · ') || '—'}
                      </Typography>
                      {row.detail ? (
                        <Typography variant="caption" color="text.secondary" display="block">{row.detail}</Typography>
                      ) : null}
                      {draft?.saved && draft.summary ? (
                        <Typography variant="caption" color="text.secondary" display="block">
                          {draft.summary}
                        </Typography>
                      ) : null}
                      {row.clarification && !draft?.saved ? (
                        <Button
                          size="small"
                          variant="outlined"
                          color="warning"
                          sx={{ mt: 1 }}
                          disabled={deciding}
                          onClick={() => {
                            setOpenClarificationId(row.clarification!.transactionId);
                            setQueueOpen(true);
                          }}
                        >
                          Add clarifications
                        </Button>
                      ) : null}
                    </TableCell>
                    <TableCell align="right">{formatImportAmount(row.amount)}</TableCell>
                    <TableCell>{formatImportDate(row.date)}</TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </TableContainer>
      )}
      {rows.length > PAGE_SIZE ? (
        <TablePagination
          component="div"
          count={rows.length}
          page={page}
          rowsPerPage={PAGE_SIZE}
          rowsPerPageOptions={[PAGE_SIZE]}
          onPageChange={(_event, nextPage) => setPage(nextPage)}
        />
      ) : null}
      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ mt: 2 }}>
        <Button
          variant="contained"
          color="success"
          onClick={onConfirm}
          disabled={deciding || unclearCount > 0}
        >
          {unclearCount > 0
            ? `Confirm and calculate (${unclearCount} still need clarification)`
            : 'Confirm and calculate'}
        </Button>
        <Button color="error" onClick={onCancel} disabled={deciding}>
          Cancel
        </Button>
      </Stack>
    </Box>
  );
};

const problemRow = (
  tone: Extract<ReviewTone, 'duplicate' | 'invalid' | 'failed'>,
  row: DuplicateAccountingRow | InvalidAccountingRow | PersistFailureAccountingRow,
  index: number,
  detail: string
): ReviewRow => ({
  key: `${tone}-${row.sourceId || row.rowIndex || index}`,
  tone,
  status: toneLabel[tone],
  rowIndex: row.rowIndex,
  sourceId: row.sourceId,
  description: row.sourceId || `Row ${row.rowIndex ?? index + 1}`,
  detail,
});

export default ImportFileReview;
