  'cat4_requires_tonne_km',
  'cat9_requires_tonne_km',
  'cat6_requires_room_nights',
  'cat6_requires_passenger_km',
  'cat7_requires_commute_km',
  'cat7_wfh_requires_hours_or_kwh',
  'bus_requires_passenger_km',
  'courier_requires_parcel_kg',
  'cat8_requires_energy_data',
  'cat10_requires_processing_data',
  'cat11_requires_use_phase_data',
  'cat12_requires_eol_activity',
  'cat13_requires_energy_data',
  'cat14_requires_franchisee_inventory',
  'cat15_requires_investee_emissions',
  'electricity_requires_bill_quantity',
  'electricity_quantity_amount_mismatch',
