const CALCULABLE_UNITS = new Set([
  'kwh', 'liter', 'kiloliter', 'kg', 'm3', 'km', 'passenger_km', 'scm',
  'tonne', 'tonkm', 'gb', 'gj', 'service_unit', 'night', 'hour'
]);

const looseUnit = (unit) => {
  const normalized = String(unit || '').toLowerCase().trim().replace(/[\s_]+/g, '-');
  if (!normalized) return '';
  if (PACK_UNIT_LABELS[normalized]) return PACK_UNIT_LABELS[normalized];
  if (['l', 'lt', 'ltr', 'litre', 'litres', 'liter', 'liters'].includes(normalized)) return 'liter';
  if (['kwh', 'kw-h', 'kilowatt-hour'].includes(normalized)) return 'kwh';
  if (['tonne-km', 'ton-km', 'tonkm', 't-km'].includes(normalized)) return 'tonkm';
  if (['kg', 'kilogram', 'kilograms'].includes(normalized)) return 'kg';
  if (['t', 'mt', 'ton', 'tonne', 'tonnes'].includes(normalized)) return 'tonne';
  if (['passenger-km', 'passenger_km', 'pkm'].includes(normalized)) return 'passenger_km';
  if (['m3', 'm^3', 'cubic-meter', 'cubic-metre'].includes(normalized)) return 'm3';
  if (['scm', 'smc'].includes(normalized)) return 'scm';
  if (['unit', 'units', 'service-unit', 'service_unit', 'visit', 'visits', 'job', 'jobs'].includes(normalized)) {
    return 'service_unit';
  }
  if (['night', 'nights', 'room-night'].includes(normalized)) return 'night';
  if (['hour', 'hours', 'hr', 'hrs'].includes(normalized)) return 'hour';
  return normalized;
};

const readSheetQuantity = (transaction = {}) => {
  const imported = transaction.metadata?.importedActivity || {};
  const quantity = Number(transaction.quantity ?? transaction.metadata?.quantity ?? imported.quantity);
  const unitRaw = String(transaction.unit || transaction.metadata?.unit || imported.unit || '').trim();
  return {
    quantity: Number.isFinite(quantity) && quantity > 0 ? quantity : 0,
    unit: looseUnit(unitRaw),
    unitRaw
  };
};

