export interface ClarificationField {
  id: string;
  metadataField: string;
  label: string;
  kind?: 'choice' | 'number' | 'text';
  required?: boolean;
  options?: Array<{ value: string; label: string }>;
}

export interface ClarificationExtraField {
  id: string;
  label: string;
  metadataField: string;
}

export interface ClarificationSourceCell {
  header: string;
  value: string;
}

export interface ClarificationSourceContext {
  sheetRow?: number | null;
  cells?: ClarificationSourceCell[];
}

export interface ClarificationQueueItem {
  transactionId: string;
  description?: string;
  amount?: number;
  date?: string | Date | null;
  rowIndex?: number | null;
  category?: string;
  subcategory?: string;
  sourceId?: string | null;
  importFileName?: string;
  vendorName?: string;
  ledgerName?: string;
  itemName?: string;
  voucherType?: string;
  sourceContext?: ClarificationSourceContext | null;
  promptId?: string | null;
  title?: string;
  question?: string;
  helper?: string;
  example?: string;
  agentMessage?: string;
  quantityLabel?: string;
  quantity?: string;
  unit?: string;
  unitOptions?: string[];
  fields?: ClarificationField[];
  extraFields?: ClarificationExtraField[];
  requireAirports?: boolean;
  requireMaterialName?: boolean;
  inputKind?: 'activity' | 'unit_price';
  factorId?: string;
  activityUnit?: string;
  unitPriceLabel?: string;
}

export interface ClarificationAnswerDraft {
  text: string;
  quantity: string;
  unit: string;
  originAirport: string;
  destinationAirport: string;
  materialName: string;
  answers: Record<string, string>;
  quantityEdited: boolean;
  unitEdited: boolean;
}

export interface ClarificationGroup {
  key: string;
  order: number;
  items: ClarificationQueueItem[];
}

const normalizeDescription = (value?: string) => String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');

const promptSignature = (item: ClarificationQueueItem) => {
  const fields = (item.fields || []).map((field) => field.metadataField).join(',');
  const extras = (item.extraFields || []).map((field) => field.metadataField).join(',');
  return [
    item.promptId || item.title || item.question || 'clarify',
    item.inputKind || 'activity',
    fields,
    extras,
    item.requireAirports ? 'airports' : '',
    item.requireMaterialName ? 'material' : '',
    item.unitPriceLabel || '',
  ].join('|');
};

export const clarificationGroupKey = (item: ClarificationQueueItem) => (
  `${promptSignature(item)}|${normalizeDescription(item.description)}`
);

export const groupClarificationItems = (items: ClarificationQueueItem[]): ClarificationGroup[] => {
  const groups = new Map<string, ClarificationGroup>();
  items.forEach((item, index) => {
    const key = clarificationGroupKey(item);
    const existing = groups.get(key);
    if (existing) {
      existing.items.push(item);
      return;
    }
    groups.set(key, { key, order: index, items: [item] });
  });
  return Array.from(groups.values());
};

export const clarificationProgress = (
  completedGroups: number,
  remainingGroups: number,
  vouchersLeft: number
) => {
  const total = completedGroups + remainingGroups;
  const voucherLabel = vouchersLeft === 1 ? 'voucher' : 'vouchers';
  return `${completedGroups} of ${total} groups done · ${vouchersLeft} ${voucherLabel} left`;
};

export const initialClarificationDraft = (group: ClarificationGroup): ClarificationAnswerDraft => {
  const quantities = new Set(group.items.map((item) => String(item.quantity || '')));
  const units = new Set(group.items.map((item) => String(item.unit || item.unitOptions?.[0] || '')));
  const first = group.items[0];
  return {
    text: '',
    quantity: quantities.size === 1 ? Array.from(quantities)[0] : '',
    unit: units.size === 1 ? Array.from(units)[0] : (first?.unitOptions?.[0] || ''),
    originAirport: '',
    destinationAirport: '',
    materialName: '',
    answers: {},
    quantityEdited: false,
    unitEdited: false,
  };
};

export const visibleClarificationFields = (
  item: ClarificationQueueItem,
  draft: ClarificationAnswerDraft
) => {
  const fields = item.fields || [];
  const productName = (field: ClarificationField) => (
    field.metadataField === 'fertilizerProductName' || field.id === 'fertilizerProductName'
  );
  const base = fields.filter((field) => !productName(field));
  const required = base.filter((field) => field.required);
  const shown = required.length > 0 ? required : base;
  if (draft.answers.fertilizerType === 'other') {
    const extra = fields.find(productName);
    if (extra) return [...shown, extra];
  }
  return shown;
};

export const resolveAnswerQuantity = (
  item: ClarificationQueueItem,
  draft: ClarificationAnswerDraft
) => {
  if (draft.quantityEdited) return draft.quantity;
  if (Number(item.quantity) > 0) return String(item.quantity);
  return draft.quantity;
};

export const resolveAnswerUnit = (
  item: ClarificationQueueItem,
  draft: ClarificationAnswerDraft
) => {
  if (draft.unitEdited) return draft.unit;
  if (String(item.unit || '').trim()) return String(item.unit);
  return draft.unit;
};

export const clarificationAnswerNote = (
  item: ClarificationQueueItem,
  draft: ClarificationAnswerDraft
) => {
  const written = draft.text.trim();
  if (written.length >= 3) return written;
  const parts = visibleClarificationFields(item, draft).flatMap((field) => {
    const value = String(draft.answers[field.metadataField] || '').trim();
    if (!value) return [];
    if (field.kind === 'choice') {
      return [field.options?.find((option) => option.value === value)?.label || value];
    }
    if (field.kind === 'number') return [`${value} ${field.label}`];
    return [value];
  });
  (item.extraFields || []).forEach((field) => {
    const value = String(draft.answers[field.metadataField] || '').trim();
    if (value) parts.push(`${value} ${field.label}`);
  });
  if (item.inputKind === 'unit_price' && Number(draft.answers.unitPriceInr) > 0) {
    parts.push(`${draft.answers.unitPriceInr} ${item.unitPriceLabel || 'per unit'}`);
  }
  if (draft.materialName.trim()) parts.push(draft.materialName.trim());
  if (parts.length > 0) return parts.join(', ');
  const quantity = resolveAnswerQuantity(item, draft);
  const unit = resolveAnswerUnit(item, draft);
  if (Number(quantity) > 0 && unit.trim()) return `${Number(quantity)} ${unit.trim()}`;
  return '';
};

export const buildClarificationAnswer = (
  item: ClarificationQueueItem,
  draft: ClarificationAnswerDraft
) => {
  const quantity = resolveAnswerQuantity(item, draft);
  const unit = resolveAnswerUnit(item, draft);
  const applied = { ...draft, quantity, unit };
  const note = clarificationAnswerNote(item, applied);
  if (item.inputKind === 'unit_price') {
    const price = Number(draft.answers.unitPriceInr);
    return {
      carbonInputBasis: 'spend' as const,
      unitPriceInr: price,
      transactionClarification: note || `${price} ${item.unitPriceLabel || 'per unit'}`,
      clarificationWithoutBill: true,
    };
  }
  return {
    carbonInputBasis: 'activity' as const,
    quantity: Number(quantity),
    unit: unit.trim(),
    transactionClarification: note,
    clarificationWithoutBill: true,
    materialName: draft.materialName.trim() || undefined,
    originAirport: draft.originAirport.trim() || undefined,
    destinationAirport: draft.destinationAirport.trim() || undefined,
    ...Object.fromEntries(
      Object.entries(draft.answers).filter(([, value]) => String(value || '').trim())
    ),
  };
};

const extrasFilled = (item: ClarificationQueueItem, draft: ClarificationAnswerDraft) => (
  (item.extraFields || []).length > 0
  && (item.extraFields || []).every((field) => Number(draft.answers[field.metadataField]) > 0)
);

export const validateClarificationGroup = (
  group: ClarificationGroup,
  draft: ClarificationAnswerDraft,
  selectedItems: ClarificationQueueItem[]
) => {
  const errors: Record<string, string> = {};
  const template = group.items[0];
  if (!template) return errors;
  if (selectedItems.length === 0) {
    errors.selection = 'Select at least one voucher.';
    return errors;
  }
  visibleClarificationFields(template, draft).forEach((field) => {
    const value = String(draft.answers[field.metadataField] || '').trim();
    const missing = field.kind === 'number' ? !(Number(value) > 0) : !value;
    const required = field.required || field.metadataField === 'fertilizerProductName';
    if (required && missing) errors[field.metadataField] = `Enter ${field.label}.`;
  });
  if (draft.answers.fertilizerType === 'other' && !String(draft.answers.fertilizerProductName || '').trim()) {
    errors.fertilizerProductName = 'Name the fertilizer product when the type is Other.';
  }
  if (template.inputKind === 'unit_price') {
    if (!(Number(draft.answers.unitPriceInr) > 0)) {
      errors.unitPriceInr = `Enter the ${template.unitPriceLabel || 'unit price'}.`;
    }
  } else if (!extrasFilled(template, draft)) {
    if (selectedItems.some((item) => !(Number(resolveAnswerQuantity(item, draft)) > 0))) {
      errors.quantity = 'Enter a quantity and unit.';
    }
    if (selectedItems.some((item) => !resolveAnswerUnit(item, draft).trim())) {
      errors.unit = 'Enter a quantity and unit.';
    }
  }
  if (template.requireAirports && (!draft.originAirport.trim() || !draft.destinationAirport.trim())) {
    if (!draft.originAirport.trim()) errors.originAirport = 'Enter the origin and destination airports.';
    if (!draft.destinationAirport.trim()) errors.destinationAirport = 'Enter the origin and destination airports.';
  }
  if (template.requireMaterialName && !draft.materialName.trim()) {
    const named = selectedItems.every((item) => clarificationAnswerNote(item, {
      ...draft,
      quantity: resolveAnswerQuantity(item, draft),
      unit: resolveAnswerUnit(item, draft),
    }).length >= 3);
    if (!named) errors.materialName = 'Name the material or activity.';
  }
  const notesReady = selectedItems.every((item) => clarificationAnswerNote(item, {
    ...draft,
    quantity: resolveAnswerQuantity(item, draft),
    unit: resolveAnswerUnit(item, draft),
  }).length >= 3);
  if (!notesReady) {
    const textShown = showFreeText(template);
    if (textShown) errors.text = 'Answer the agent before this row can be calculated.';
    else if (!errors.quantity && !errors.unitPriceInr) {
      errors.quantity = 'Answer the agent before this row can be calculated.';
    }
  }
  return errors;
};

export const showFreeText = (item: ClarificationQueueItem) => (
  (item.fields || []).filter((field) => field.metadataField !== 'fertilizerProductName' && field.id !== 'fertilizerProductName').length === 0
  && item.inputKind !== 'unit_price'
  && item.promptId !== 'activity_quantity_missing'
  && item.promptId !== 'service_count_missing'
);

export const quantitiesDiffer = (group: ClarificationGroup) => (
  new Set(group.items.map((item) => String(item.quantity || ''))).size > 1
);
